contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        uint potBefore = c.pot(); if (__ESBMC_reverted()) return;
        uint contractBalanceBefore = address(c).balance;

        bool reverted;
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint potAfter = c.pot(); if (__ESBMC_reverted()) return;
        uint contractBalanceAfter = address(c).balance;

        assert(
            (amount == 10 && !reverted && (potAfter == 0 || potAfter == potBefore + 10) &&
                contractBalanceAfter == contractBalanceBefore + 10 - (potBefore + 10 - potAfter)) ||
            (amount != 10 && reverted && potAfter == potBefore && contractBalanceAfter == contractBalanceBefore)
        );
    }

    receive() external payable {}
}

